import { createHmac, randomBytes, timingSafeEqual } from 'node:crypto';
import { lookup as dnsLookup } from 'node:dns/promises';
import { request as httpRequest, type IncomingMessage } from 'node:http';
import { request as httpsRequest } from 'node:https';
import { BlockList, isIP } from 'node:net';
import { Hono, type Context } from 'hono';
import { clientIp, type Env } from './context.js';
import { RateLimiter } from './ratelimit.js';
import { isLanguage } from './i18n.js';
import { decodeEntities } from './richtext.js';
import { log } from './log.js';

// Link previews generated by klatchly. The server fetches arbitrary public URLs on the user's behalf, so
// every hop goes through an SSRF guard: http(s) on ports 80/443 only, every resolved address must be
// public (no loopback, private, link-local, CGNAT, multicast, reserved, docker networks, metadata...),
// the socket connects to the vetted address itself (no second DNS lookup, so no rebinding), redirects
// are re-checked (3 max), 5 s overall, bounded bodies, no cookies. Images are only fetched when the URL
// was extracted by us (HMAC-signed), so /api/preview-img is not an open proxy.

const blocked4 = new BlockList();
const blocked6 = new BlockList();
for (const [net, bits] of [
  ['0.0.0.0', 8], ['10.0.0.0', 8], ['100.64.0.0', 10], ['127.0.0.0', 8], ['169.254.0.0', 16], ['172.16.0.0', 12],
  ['192.0.0.0', 24], ['192.0.2.0', 24], ['192.88.99.0', 24], ['192.168.0.0', 16], ['198.18.0.0', 15],
  ['198.51.100.0', 24], ['203.0.113.0', 24], ['224.0.0.0', 4], ['240.0.0.0', 4],
] as const) blocked4.addSubnet(net, bits, 'ipv4');
for (const [net, bits] of [
  ['64:ff9b::', 96], ['64:ff9b:1::', 48], ['100::', 64], ['2001::', 23],
  ['2001:db8::', 32], ['2002::', 16], ['fc00::', 7], ['fe80::', 10], ['fec0::', 10], ['ff00::', 8],
] as const) blocked6.addSubnet(net, bits, 'ipv6');

/** Public unicast address only (IPv4-mapped / NAT64 / 6to4 forms are refused outright). */
export function isPublicIP(ip: string): boolean {
  const v = isIP(ip);
  if (v === 4) return !blocked4.check(ip, 'ipv4');
  if (v === 6) {
    // Only global unicast (2000::/3, which excludes ::1, ::ffff:a.b.c.d, fc00::/7, fe80::/10, ff00::/8...)
    // outside the reserved blocks above.
    const first = parseInt(ip.split(':')[0] || '0', 16);
    if (!ip.includes(':') || (first & 0xe000) !== 0x2000) return false;
    return !blocked6.check(ip, 'ipv6');
  }
  return false;
}

export interface Guard {
  resolve(host: string): Promise<string[]>;
  allowIP(ip: string): boolean;
  allowPort(port: number): boolean;
}

export const defaultGuard: Guard = {
  resolve: async (host) => (await dnsLookup(host, { all: true, verbatim: true })).map((a) => a.address),
  allowIP: isPublicIP,
  allowPort: (p) => p === 80 || p === 443,
};

/** Syntactic URL check: http(s), no credentials, no fragment games, sane length. */
export function parseTarget(raw: unknown): URL | null {
  if (typeof raw !== 'string' || raw.length > 2048 || /[\u0000- \u007f]/.test(raw)) return null;
  let u: URL;
  try {
    u = new URL(raw);
  } catch {
    return null;
  }
  if ((u.protocol !== 'http:' && u.protocol !== 'https:') || u.username || u.password || !u.hostname) return null;
  u.hash = '';
  return u;
}

export class BlockedError extends Error {}

type Fetched = { url: URL; status: number; type: string; body: Buffer };

/** GET with the SSRF guard on every hop. Resolves with at most `maxBytes` of body (truncated flag-free). */
export async function guardedGet(
  start: URL,
  opts: { maxBytes: number; accept: (type: string) => boolean; lang?: string; timeoutMs?: number; guard?: Guard; truncate?: boolean },
): Promise<Fetched> {
  const guard = opts.guard ?? defaultGuard;
  const deadline = AbortSignal.timeout(opts.timeoutMs ?? 5000);
  let url = start;
  for (let hop = 0; hop <= 3; hop++) {
    const port = url.port ? Number(url.port) : url.protocol === 'https:' ? 443 : 80;
    if (!guard.allowPort(port)) throw new BlockedError('port');
    const host = url.hostname.replace(/^\[|\]$/g, '');
    const addrs = isIP(host) ? [host] : await guard.resolve(host);
    if (!addrs.length || !addrs.every((a) => guard.allowIP(a))) throw new BlockedError('address');
    const ip = addrs[0]!;
    const family = isIP(ip);
    const res = await new Promise<IncomingMessage>((resolve, reject) => {
      const req = (url.protocol === 'https:' ? httpsRequest : httpRequest)(
        {
          host,
          port,
          path: url.pathname + url.search,
          method: 'GET',
          // Connect to the vetted address only: no second resolution (DNS rebinding).
          lookup: ((_h: string, o: { all?: boolean }, cb: (...a: unknown[]) => void) =>
            o?.all ? cb(null, [{ address: ip, family }]) : cb(null, ip, family)) as never,
          servername: isIP(host) ? undefined : host,
          headers: {
            // Generic browser UA (no product name): several CDNs refuse unknown bots.
            'User-Agent': 'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/130.0 Safari/537.36',
            Accept: 'text/html,application/xhtml+xml,image/avif,image/webp,image/png,image/jpeg,image/gif;q=0.9,*/*;q=0.1',
            ...(opts.lang ? { 'Accept-Language': `${opts.lang},en;q=0.5` } : {}),
          },
          signal: deadline,
        },
        resolve,
      );
      req.on('error', reject);
      req.end();
    });
    const status = res.statusCode ?? 0;
    if (status >= 300 && status < 400 && res.headers.location) {
      res.resume();
      const next = parseTarget(new URL(res.headers.location, url).href);
      if (!next) throw new BlockedError('redirect');
      url = next;
      continue;
    }
    const type = String(res.headers['content-type'] ?? '').toLowerCase();
    if (status !== 200 || !opts.accept(type.split(';')[0]!.trim())) {
      res.resume();
      throw new BlockedError(`status ${status} ${type.split(';')[0]}`);
    }
    const declared = Number(res.headers['content-length'] ?? 0);
    if (!opts.truncate && declared > opts.maxBytes) {
      res.destroy();
      throw new BlockedError('too large');
    }
    const chunks: Buffer[] = [];
    let n = 0;
    for await (const c of res as AsyncIterable<Buffer>) {
      n += c.length;
      if (n > opts.maxBytes) {
        if (!opts.truncate) {
          res.destroy();
          throw new BlockedError('too large');
        }
        chunks.push(c.subarray(0, c.length - (n - opts.maxBytes)));
        res.destroy();
        break;
      }
      chunks.push(c);
    }
    return { url, status, type, body: Buffer.concat(chunks) };
  }
  throw new BlockedError('redirects');
}

export interface Preview {
  url: string;
  title?: string;
  description?: string;
  siteName?: string;
  image?: string;
}

const clip = (s: string | undefined, n: number) => {
  const t = s ? decodeEntities(s).replace(/\s+/g, ' ').trim() : '';
  return t ? (t.length > n ? `${t.slice(0, n - 1)}…` : t) : undefined;
};

function attrs(tag: string): Record<string, string> {
  const out: Record<string, string> = {};
  for (const m of tag.matchAll(/([a-zA-Z_:][-a-zA-Z0-9_:.]*)\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'>]+))/g)) {
    out[m[1]!.toLowerCase()] = m[2] ?? m[3] ?? m[4] ?? '';
  }
  return out;
}

function decode(body: Buffer, type: string): string {
  let charset = /charset=([\w-]+)/i.exec(type)?.[1];
  if (!charset) charset = /<meta[^>]+charset=["']?([\w-]+)/i.exec(body.subarray(0, 2048).toString('latin1'))?.[1];
  try {
    return new TextDecoder(charset ?? 'utf-8').decode(body);
  } catch {
    return new TextDecoder('utf-8').decode(body);
  }
}

/** og:/twitter: metadata and <title> from the page head (no DOM, no scripts). */
export function parseHead(html: string, base: URL): Omit<Preview, 'url'> & { imageURL?: string } {
  const end = html.search(/<\/head>|<body[\s>]/i);
  const head = end > 0 ? html.slice(0, end) : html;
  const meta: Record<string, string> = {};
  for (const m of head.matchAll(/<meta\b[^>]*>/gi)) {
    const a = attrs(m[0]);
    const key = (a.property ?? a.name ?? '').toLowerCase();
    if (key && a.content !== undefined && !(key in meta)) meta[key] = a.content;
  }
  const title = meta['og:title'] ?? meta['twitter:title'] ?? /<title[^>]*>([\s\S]*?)<\/title>/i.exec(head)?.[1];
  const description = meta['og:description'] ?? meta['twitter:description'] ?? meta.description;
  let imageURL: string | undefined;
  const img = meta['og:image:secure_url'] ?? meta['og:image'] ?? meta['og:image:url'] ?? meta['twitter:image'] ?? meta['twitter:image:src'];
  if (img) imageURL = parseTarget(new URL(decodeEntities(img), base).href)?.href;
  return { title: clip(title, 200), description: clip(description, 300), siteName: clip(meta['og:site_name'], 100), imageURL };
}

// Signed image references: only URLs we extracted can be fetched through /api/preview-img.
const KEY = randomBytes(32);
const sign = (u: string) => createHmac('sha256', KEY).update(u).digest('base64url');
export function imageRef(u: string): string {
  return `/api/preview-img/p.jpg?u=${encodeURIComponent(u)}&s=${sign(u)}`;
}
export function verifyImageRef(u: string, s: string): boolean {
  const a = Buffer.from(sign(u));
  const b = Buffer.from(s);
  return a.length === b.length && timingSafeEqual(a, b);
}

// LRU-ish cache: insertion order, refreshed on hit. Failures are cached too.
const DAY = 24 * 3600 * 1000;
const cache = new Map<string, { at: number; ttl: number; p: Preview }>();
function cached(k: string): Preview | undefined {
  const e = cache.get(k);
  if (!e) return undefined;
  if (Date.now() - e.at > e.ttl) {
    cache.delete(k);
    return undefined;
  }
  cache.delete(k);
  cache.set(k, e);
  return e.p;
}
function remember(k: string, p: Preview, ttl: number) {
  cache.set(k, { at: Date.now(), ttl, p });
  if (cache.size > 1000) cache.delete(cache.keys().next().value!);
}

const inflight = new Map<string, Promise<Preview>>();

export async function preview(target: URL, lang?: string, guard?: Guard): Promise<Preview> {
  const k = `${lang ?? ''} ${target.href}`;
  const hit = cached(k);
  if (hit) return hit;
  let p = inflight.get(k);
  if (!p) {
    p = (async () => {
      try {
        const r = await guardedGet(target, {
          maxBytes: 512 * 1024,
          truncate: true,
          accept: (t) => t === 'text/html' || t === 'application/xhtml+xml',
          lang,
          guard,
        });
        const h = parseHead(decode(r.body, r.type), r.url);
        const out: Preview = {
          url: target.href,
          ...(h.title ? { title: h.title } : {}),
          ...(h.description ? { description: h.description } : {}),
          ...(h.siteName ? { siteName: h.siteName } : {}),
          ...(h.imageURL ? { image: imageRef(h.imageURL) } : {}),
        };
        remember(k, out, out.title ? DAY : 6 * 3600 * 1000);
        return out;
      } catch (e) {
        log('preview', 'no preview', { host: target.hostname, reason: e instanceof BlockedError ? e.message.slice(0, 40) : 'fetch' });
        const out = { url: target.href };
        remember(k, out, 6 * 3600 * 1000);
        return out;
      } finally {
        inflight.delete(k);
      }
    })();
    inflight.set(k, p);
  }
  return p;
}

const IMAGE_TYPES = /^image\/(jpeg|png|gif|webp|avif)$/;
const previewLimiter = new RateLimiter(10 * 60 * 1000, 300, 600);
const imageLimiter = new RateLimiter(10 * 60 * 1000, 600, 1200);

export const previewRoutes = new Hono<Env>();

previewRoutes.get('/preview', async (c: Context) => {
  if (!previewLimiter.allow(clientIp(c))) return c.json({ error: 'rate_limited' }, 429);
  const target = parseTarget(c.req.query('url'));
  const lang = c.req.query('lang');
  if (!target || (lang !== undefined && !isLanguage(lang))) return c.json({ error: 'bad_request' }, 400);
  const p = await preview(target, lang);
  return c.json(p, 200, { 'Cache-Control': 'private, max-age=3600' });
});

const previewImg = async (c: Context) => {
  if (!imageLimiter.allow(clientIp(c))) return c.json({ error: 'rate_limited' }, 429);
  const u = c.req.query('u') ?? '';
  const s = c.req.query('s') ?? '';
  const target = parseTarget(u);
  if (!target || target.href !== u || !verifyImageRef(u, s)) return c.json({ error: 'bad_request' }, 400);
  try {
    const r = await guardedGet(target, { maxBytes: 5 * 1024 * 1024, accept: (t) => IMAGE_TYPES.test(t) });
    return c.body(new Uint8Array(r.body), 200, {
      'Content-Type': r.type.split(';')[0]!.trim(),
      'Content-Length': String(r.body.length),
      'Content-Security-Policy': "sandbox; default-src 'none'",
      'X-Content-Type-Options': 'nosniff',
      'Cache-Control': 'private, max-age=86400',
      'Cross-Origin-Resource-Policy': 'same-origin',
    });
  } catch (e) {
    log('preview', 'image refused', { host: target.hostname, reason: e instanceof BlockedError ? e.message.slice(0, 40) : 'fetch' });
    return c.body(null, 404);
  }
};
previewRoutes.get('/preview-img', previewImg);
previewRoutes.get('/preview-img/:file{[a-z0-9]{1,16}\\.[a-z0-9]{2,5}}', previewImg);
